206: void OutputImage(Gdiplus::GpGraphics* graphics,
207:                  RetainPtr<const CFX_DIBBase> source,
208:                  int dest_left,
209:                  int dest_top,
210:                  int dest_width,
211:                  int dest_height) {
212:   CHECK_EQ(FXDIB_Format::kBgra, source->GetFormat());
213:   const CGdiplusExt& gdi_plus_ext = GetGdiplusExt();
214: 
215:   RetainPtr<const CFX_DIBitmap> realized_source = source->RealizeIfNeeded();
216:   if (!realized_source) {
217:     return;
218:   }
219: 
220:   // `GdipCreateBitmapFromScan0()` requires a `BYTE*` scanline buffer, but in
221:   // this case, the bitmap only gets read by `GdipDrawImagePointsI()`, then
222:   // disposed of, so it's safe to cast away `const` here.
223:   uint8_t* scan0 = const_cast<uint8_t*>(realized_source->GetBuffer().data());
224:   Gdiplus::GpBitmap* bitmap = nullptr;
225:   CALLFUNC(gdi_plus_ext, GdipCreateBitmapFromScan0, realized_source->GetWidth(),
226:            realized_source->GetHeight(), realized_source->GetPitch(),
227:            PixelFormat32bppARGB, scan0, &bitmap);
228:   if (dest_height < 0) {
229:     dest_height--;
230:   }
231:   if (dest_width < 0) {
232:     dest_width--;
233:   }
234:   const Gdiplus::Point destination_points[] = {
235:       Gdiplus::Point(dest_left, dest_top),
236:       Gdiplus::Point(dest_left + dest_width, dest_top),
237:       Gdiplus::Point(dest_left, dest_top + dest_height)};
238:   CALLFUNC(gdi_plus_ext, GdipDrawImagePointsI, graphics, bitmap,
239:            destination_points, std::size(destination_points));
240:   CALLFUNC(gdi_plus_ext, GdipDisposeImage, bitmap);
241: }
