243: Gdiplus::GpPen* GdipCreatePenImpl(const CFX_GraphStateData* pGraphState,
244:                                   const CFX_Matrix* pMatrix,
245:                                   DWORD argb,
246:                                   bool bTextMode) {
247:   const CGdiplusExt& gdi_plus_ext = GetGdiplusExt();
248:   float width = pGraphState->line_width();
249:   if (!bTextMode) {
250:     float unit = pMatrix
251:                      ? 1.0f / ((pMatrix->GetXUnit() + pMatrix->GetYUnit()) / 2)
252:                      : 1.0f;
253:     width = std::max(width, unit);
254:   }
255:   Gdiplus::GpPen* pPen = nullptr;
256:   CALLFUNC(gdi_plus_ext, GdipCreatePen1, static_cast<Gdiplus::ARGB>(argb),
257:            width, Gdiplus::UnitWorld, &pPen);
258:   Gdiplus::LineCap lineCap = Gdiplus::LineCapFlat;
259:   Gdiplus::DashCap dashCap = Gdiplus::DashCapFlat;
260:   bool bDashExtend = false;
261:   switch (pGraphState->line_cap()) {
262:     case CFX_GraphStateData::LineCap::kButt:
263:       lineCap = Gdiplus::LineCapFlat;
264:       break;
265:     case CFX_GraphStateData::LineCap::kRound:
266:       lineCap = Gdiplus::LineCapRound;
267:       dashCap = Gdiplus::DashCapRound;
268:       bDashExtend = true;
269:       break;
270:     case CFX_GraphStateData::LineCap::kSquare:
271:       lineCap = Gdiplus::LineCapSquare;
272:       bDashExtend = true;
273:       break;
274:   }
275:   CALLFUNC(gdi_plus_ext, GdipSetPenLineCap197819, pPen, lineCap, lineCap,
276:            dashCap);
277:   Gdiplus::LineJoin lineJoin = Gdiplus::LineJoinMiterClipped;
278:   switch (pGraphState->line_join()) {
279:     case CFX_GraphStateData::LineJoin::kMiter:
280:       lineJoin = Gdiplus::LineJoinMiterClipped;
281:       break;
282:     case CFX_GraphStateData::LineJoin::kRound:
283:       lineJoin = Gdiplus::LineJoinRound;
284:       break;
285:     case CFX_GraphStateData::LineJoin::kBevel:
286:       lineJoin = Gdiplus::LineJoinBevel;
287:       break;
288:   }
289:   CALLFUNC(gdi_plus_ext, GdipSetPenLineJoin, pPen, lineJoin);
290:   const std::vector<float>& dash_array = pGraphState->dash_array();
291:   if (!dash_array.empty()) {
292:     float* gdi_dash_array =
293:         FX_Alloc(float, FxAlignToBoundary<2>(dash_array.size()));
294:     int nCount = 0;
295:     float on_leftover = 0;
296:     float off_leftover = 0;
297:     for (size_t i = 0; i < dash_array.size(); i += 2) {
298:       float on_phase = dash_array[i];
299:       float off_phase =
300:           i + 1 < dash_array.size() ? dash_array[i + 1] : on_phase;
301:       on_phase /= width;
302:       off_phase /= width;
303:       if (on_phase + off_phase <= 0.00002f) {
304:         on_phase = 0.1f;
305:         off_phase = 0.1f;
306:       }
307:       if (bDashExtend) {
308:         if (off_phase < 1) {
309:           off_phase = 0;
310:         } else {
311:           --off_phase;
312:         }
313:         ++on_phase;
314:       }
315:       if (on_phase == 0 || off_phase == 0) {
316:         if (nCount == 0) {
317:           on_leftover += on_phase;
318:           off_leftover += off_phase;
319:         } else {
320:           UNSAFE_TODO({
321:             gdi_dash_array[nCount - 2] += on_phase;
322:             gdi_dash_array[nCount - 1] += off_phase;
323:           });
324:         }
325:       } else {
326:         UNSAFE_TODO({
327:           gdi_dash_array[nCount++] = on_phase + on_leftover;
328:           on_leftover = 0;
329:           gdi_dash_array[nCount++] = off_phase + off_leftover;
330:           off_leftover = 0;
331:         });
332:       }
333:     }
334:     CALLFUNC(gdi_plus_ext, GdipSetPenDashArray, pPen, gdi_dash_array, nCount);
335:     float phase = pGraphState->dash_phase();
336:     if (bDashExtend) {
337:       if (phase < 0.5f) {
338:         phase = 0;
339:       } else {
340:         phase -= 0.5f;
341:       }
342:     }
343:     CALLFUNC(gdi_plus_ext, GdipSetPenDashOffset, pPen, phase);
344:     FX_Free(gdi_dash_array);
345:     gdi_dash_array = nullptr;
346:   }
347:   CALLFUNC(gdi_plus_ext, GdipSetPenMiterLimit, pPen,
348:            pGraphState->miter_limit());
349:   return pPen;
350: }
