352: std::optional<std::pair<size_t, size_t>> IsSmallTriangle(
353:     pdfium::span<const Gdiplus::PointF> points,
354:     const CFX_Matrix* pMatrix) {
355:   static constexpr std::array<std::pair<const size_t, const size_t>, 3> kPairs =
356:       {{{1, 2}, {0, 2}, {0, 1}}};
357:   for (size_t i = 0; i < std::size(kPairs); ++i) {
358:     size_t pair1 = kPairs[i].first;
359:     size_t pair2 = kPairs[i].second;
360:     CFX_PointF p1(points[pair1].X, points[pair1].Y);
361:     CFX_PointF p2(points[pair2].X, points[pair2].Y);
362:     if (pMatrix) {
363:       p1 = pMatrix->Transform(p1);
364:       p2 = pMatrix->Transform(p2);
365:     }
366:     CFX_PointF diff = p1 - p2;
367:     float distance_square = (diff.x * diff.x) + (diff.y * diff.y);
368:     if (distance_square < 2.25f) {
369:       return std::make_pair(i, pair1);
370:     }
371:   }
372:   return std::nullopt;
373: }
