380:   // IUnknown
381:   HRESULT STDMETHODCALLTYPE QueryInterface(REFIID iid,
382:                                            void** ppvObject) override {
383:     if (iid == __uuidof(IUnknown) || iid == __uuidof(IStream) ||
384:         iid == __uuidof(ISequentialStream)) {
385:       *ppvObject = static_cast<IStream*>(this);
386:       AddRef();
387:       return S_OK;
388:     }
389:     return E_NOINTERFACE;
390:   }
391:   ULONG STDMETHODCALLTYPE AddRef() override {
392:     return (ULONG)InterlockedIncrement(&ref_count_);
393:   }
394:   ULONG STDMETHODCALLTYPE Release() override {
395:     ULONG res = (ULONG)InterlockedDecrement(&ref_count_);
396:     if (res == 0) {
397:       delete this;
398:     }
399:     return res;
400:   }
401: 
402:   // ISequentialStream
403:   HRESULT STDMETHODCALLTYPE Read(void* output,
404:                                  ULONG cb,
405:                                  ULONG* pcbRead) override {
406:     if (pcbRead) {
407:       *pcbRead = 0;
408:     }
409: 
410:     if (read_pos_ >= inter_stream_.tellp()) {
411:       return HRESULT_FROM_WIN32(ERROR_END_OF_MEDIA);
412:     }
413: 
414:     size_t bytes_left = pdfium::checked_cast<size_t>(
415:         std::streamoff(inter_stream_.tellp()) - read_pos_);
416:     size_t bytes_out = std::min(pdfium::checked_cast<size_t>(cb), bytes_left);
417:     UNSAFE_TODO(FXSYS_memcpy(output, inter_stream_.str().c_str() + read_pos_,
418:                              bytes_out));
419:     read_pos_ += bytes_out;
420:     if (pcbRead) {
421:       *pcbRead = (ULONG)bytes_out;
422:     }
423: 
424:     return S_OK;
425:   }
426:   HRESULT STDMETHODCALLTYPE Write(const void* input,
427:                                   ULONG cb,
428:                                   ULONG* pcbWritten) override {
429:     if (cb <= 0) {
430:       if (pcbWritten) {
431:         *pcbWritten = 0;
432:       }
433:       return S_OK;
434:     }
435:     inter_stream_.write(reinterpret_cast<const char*>(input), cb);
436:     if (pcbWritten) {
437:       *pcbWritten = cb;
438:     }
439:     return S_OK;
440:   }
441: 
442:   // IStream
443:   HRESULT STDMETHODCALLTYPE SetSize(ULARGE_INTEGER) override {
444:     return E_NOTIMPL;
445:   }
446:   HRESULT STDMETHODCALLTYPE CopyTo(IStream*,
447:                                    ULARGE_INTEGER,
448:                                    ULARGE_INTEGER*,
449:                                    ULARGE_INTEGER*) override {
450:     return E_NOTIMPL;
451:   }
452:   HRESULT STDMETHODCALLTYPE Commit(DWORD) override { return E_NOTIMPL; }
453:   HRESULT STDMETHODCALLTYPE Revert() override { return E_NOTIMPL; }
454:   HRESULT STDMETHODCALLTYPE LockRegion(ULARGE_INTEGER,
455:                                        ULARGE_INTEGER,
456:                                        DWORD) override {
457:     return E_NOTIMPL;
458:   }
459:   HRESULT STDMETHODCALLTYPE UnlockRegion(ULARGE_INTEGER,
460:                                          ULARGE_INTEGER,
461:                                          DWORD) override {
462:     return E_NOTIMPL;
463:   }
464:   HRESULT STDMETHODCALLTYPE Clone(IStream** stream) override {
465:     return E_NOTIMPL;
466:   }
467:   HRESULT STDMETHODCALLTYPE Seek(LARGE_INTEGER liDistanceToMove,
468:                                  DWORD dwOrigin,
469:                                  ULARGE_INTEGER* lpNewFilePointer) override {
470:     std::streamoff start;
471:     std::streamoff new_read_position;
472:     switch (dwOrigin) {
473:       case STREAM_SEEK_SET:
474:         start = 0;
475:         break;
476:       case STREAM_SEEK_CUR:
477:         start = read_pos_;
478:         break;
479:       case STREAM_SEEK_END:
480:         if (inter_stream_.tellp() < 0) {
481:           return STG_E_SEEKERROR;
482:         }
483:         start = inter_stream_.tellp();
484:         break;
485:       default:
486:         return STG_E_INVALIDFUNCTION;
487:     }
488:     new_read_position = start + liDistanceToMove.QuadPart;
489:     if (new_read_position > inter_stream_.tellp()) {
490:       return STG_E_SEEKERROR;
491:     }
492: 
493:     read_pos_ = new_read_position;
494:     if (lpNewFilePointer) {
495:       lpNewFilePointer->QuadPart = read_pos_;
496:     }
497: 
498:     return S_OK;
499:   }
500:   HRESULT STDMETHODCALLTYPE Stat(STATSTG* pStatstg,
501:                                  DWORD grfStatFlag) override {
502:     if (!pStatstg) {
503:       return STG_E_INVALIDFUNCTION;
504:     }
505: 
506:     UNSAFE_TODO(ZeroMemory(pStatstg, sizeof(STATSTG)));
507: 
508:     if (inter_stream_.tellp() < 0) {
509:       return STG_E_SEEKERROR;
510:     }
511: 
512:     pStatstg->cbSize.QuadPart = inter_stream_.tellp();
513:     return S_OK;
514:   }
515: 
516:  private:
517:   LONG ref_count_ = 1;
518:   std::streamoff read_pos_ = 0;
519:   fxcrt::ostringstream inter_stream_;
520: };
