583: bool CGdiplusExt::DrawPath(HDC hDC,
584:                            const CFX_Path& path,
585:                            const CFX_Matrix* pObject2Device,
586:                            const CFX_GraphStateData* pGraphState,
587:                            uint32_t fill_argb,
588:                            uint32_t stroke_argb,
589:                            const CFX_FillRenderOptions& fill_options) {
590:   pdfium::span<const CFX_Path::Point> points = path.GetPoints();
591:   if (points.empty()) {
592:     return true;
593:   }
594: 
595:   Gdiplus::GpGraphics* pGraphics = nullptr;
596:   const CGdiplusExt& gdi_plus_ext = GetGdiplusExt();
597:   CALLFUNC(gdi_plus_ext, GdipCreateFromHDC, hDC, &pGraphics);
598:   CALLFUNC(gdi_plus_ext, GdipSetPageUnit, pGraphics, Gdiplus::UnitPixel);
599:   CALLFUNC(gdi_plus_ext, GdipSetPixelOffsetMode, pGraphics,
600:            Gdiplus::PixelOffsetModeHalf);
601:   Gdiplus::GpMatrix* pMatrix = nullptr;
602:   if (pObject2Device) {
603:     CALLFUNC(gdi_plus_ext, GdipCreateMatrix2, pObject2Device->a,
604:              pObject2Device->b, pObject2Device->c, pObject2Device->d,
605:              pObject2Device->e, pObject2Device->f, &pMatrix);
606:     CALLFUNC(gdi_plus_ext, GdipSetWorldTransform, pGraphics, pMatrix);
607:   }
608:   std::vector<Gdiplus::PointF> gp_points(points.size());
609:   std::vector<BYTE> gp_types(points.size());
610:   int nSubPathes = 0;
611:   bool bSubClose = false;
612:   bool bSmooth = false;
613:   size_t pos_subclose = 0;
614:   size_t startpoint = 0;
615:   for (size_t i = 0; i < points.size(); ++i) {
616:     gp_points[i].X = points[i].point_.x;
617:     gp_points[i].Y = points[i].point_.y;
618: 
619:     CFX_PointF pos = points[i].point_;
620:     if (pObject2Device) {
621:       pos = pObject2Device->Transform(pos);
622:     }
623: 
624:     if (pos.x > 50000.0f) {
625:       gp_points[i].X = 50000.0f;
626:     }
627:     if (pos.x < -50000.0f) {
628:       gp_points[i].X = -50000.0f;
629:     }
630:     if (pos.y > 50000.0f) {
631:       gp_points[i].Y = 50000.0f;
632:     }
633:     if (pos.y < -50000.0f) {
634:       gp_points[i].Y = -50000.0f;
635:     }
