41:       pBitmap->GetWritableBuffer().data(), pBitmap->GetWidth(),
42:       pBitmap->GetHeight(), 8, pBitmap->GetPitch(), colorSpace, bmpInfo);
43:   CGColorSpaceRelease(colorSpace);
