63: bool CFX_FolderFontInfo::FindFamilyNameMatch(
64:     ByteStringView family_name,
65:     const ByteString& installed_font_name) {
66:   std::optional<size_t> result = installed_font_name.Find(family_name, 0);
67:   if (!result.has_value()) {
68:     return false;
69:   }
