71:   size_t next_index = result.value() + family_name.GetLength();
72:   // Rule out the case that |family_name| is a substring of
73:   // |installed_font_name| but their family names are actually different words.
74:   // For example: "Univers" and "Universal" are not a match because they have
75:   // different family names, but "Univers" and "Univers Bold" are a match.
76:   if (installed_font_name.IsValidIndex(next_index) &&
77:       FXSYS_IsLowerASCII(installed_font_name[next_index])) {
78:     return false;
