139: void CFX_FolderFontInfo::ScanPath(const ByteString& path) {
140:   std::unique_ptr<FX_Folder> handle = FX_Folder::OpenFolder(path);
141:   if (!handle) {
142:     return;
143:   }
144: 
145:   ByteString filename;
146:   bool bFolder;
147:   while (handle->GetNextFile(&filename, &bFolder)) {
148:     if (bFolder) {
149:       if (filename == "." || filename == "..") {
150:         continue;
151:       }
152:     } else {
153:       ByteString ext = filename.Last(4);
154:       ext.MakeLower();
155:       if (ext != ".ttf" && ext != ".ttc" && ext != ".otf") {
156:         continue;
157:       }
158:     }
159: 
160:     ByteString fullpath = path;
161: #if BUILDFLAG(IS_WIN)
162:     fullpath += "\\";
163: #else
164:     fullpath += "/";
165: #endif
166: 
167:     fullpath += filename;
168:     bFolder ? ScanPath(fullpath) : ScanFile(fullpath);
169:   }
170: }
