172: void CFX_FolderFontInfo::ScanFile(const ByteString& path) {
173:   std::unique_ptr<FILE, FxFileCloser> pFile(fopen(path.c_str(), "rb"));
174:   if (!pFile) {
175:     return;
176:   }
177: 
178:   fseek(pFile.get(), 0, SEEK_END);
179: 
180:   FX_FILESIZE filesize = ftell(pFile.get());
181:   fseek(pFile.get(), 0, SEEK_SET);
182: 
183:   uint8_t buffer[12];
184:   if (fxcrt::spanread(buffer, pFile.get()).size() != sizeof(buffer)) {
185:     return;
186:   }
187:   uint32_t magic = fxcrt::GetUInt32MSBFirst(pdfium::span(buffer).first<4u>());
188:   if (magic != SystemFontInfoIface::kTableTTCF) {
189:     ReportFace(path, pFile.get(), filesize, 0);
190:     return;
191:   }
192: 
193:   uint32_t nFaces =
194:       fxcrt::GetUInt32MSBFirst(pdfium::span(buffer).subspan<8u, 4u>());
195:   FX_SAFE_SIZE_T safe_face_bytes = nFaces;
196:   safe_face_bytes *= 4;
197:   if (!safe_face_bytes.IsValid()) {
198:     return;
199:   }
200: 
201:   auto offsets =
202:       FixedSizeDataVector<uint8_t>::Uninit(safe_face_bytes.ValueOrDie());
203:   if (fxcrt::spanread(offsets.span(), pFile.get()).size() != offsets.size()) {
204:     return;
205:   }
206: 
207:   for (uint32_t i = 0; i < nFaces; i++) {
208:     ReportFace(path, pFile.get(), filesize,
209:                fxcrt::GetUInt32MSBFirst(offsets.subspan(i * 4).first<4u>()));
210:   }
211: }
