213: void CFX_FolderFontInfo::ReportFace(const ByteString& path,
214:                                     FILE* pFile,
215:                                     FX_FILESIZE filesize,
216:                                     uint32_t offset) {
217:   if (fseek(pFile, offset, SEEK_SET) < 0) {
218:     return;
