255:   auto pInfo =
256:       std::make_unique<FontFaceInfo>(path, facename, tables, offset, filesize);
257:   static constexpr uint32_t kOs2Tag =
258:       CFX_FontMapper::MakeTag('O', 'S', '/', '2');
