272:       pInfo->charsets_ |= FX_CharsetFlag::kMSWin_Cyrillic;
273:     }
274:     if (codepages & (1U << 3)) {
275:       mapper_->AddInstalledFont(facename, FX_Charset::kMSWin_Greek);
276:       pInfo->charsets_ |= FX_CharsetFlag::kMSWin_Greek;
277:     }
278:     if (codepages & (1U << 4)) {
279:       mapper_->AddInstalledFont(facename, FX_Charset::kMSWin_Turkish);
280:       pInfo->charsets_ |= FX_CharsetFlag::kMSWin_Turkish;
281:     }
282:     if (codepages & (1U << 5)) {
283:       mapper_->AddInstalledFont(facename, FX_Charset::kMSWin_Hebrew);
284:       pInfo->charsets_ |= FX_CharsetFlag::kMSWin_Hebrew;
285:     }
286:     if (codepages & (1U << 6)) {
287:       mapper_->AddInstalledFont(facename, FX_Charset::kMSWin_Arabic);
288:       pInfo->charsets_ |= FX_CharsetFlag::kMSWin_Arabic;
289:     }
290:     if (codepages & (1U << 7)) {
291:       mapper_->AddInstalledFont(facename, FX_Charset::kMSWin_Baltic);
292:       pInfo->charsets_ |= FX_CharsetFlag::kMSWin_Baltic;
293:     }
294:     if (codepages & (1U << 8)) {
295:       mapper_->AddInstalledFont(facename, FX_Charset::kMSWin_Vietnamese);
296:       pInfo->charsets_ |= FX_CharsetFlag::kMSWin_Vietnamese;
