365: void* CFX_FolderFontInfo::FindFont(int weight,
366:                                    bool italic,
367:                                    FX_Charset charset,
368:                                    int pitch_family,
369:                                    const ByteString& family,
370:                                    bool must_match_name) {
371:   FontFaceInfo* pFind = nullptr;
372:   FX_CharsetFlag charset_flag = FX_CharsetFlagForCharset(charset);
373:   int32_t iBestSimilar = 0;
374:   if (must_match_name) {
375:     // Try a direct lookup for either a perfect score or to determine a
376:     // baseline similarity score.
377:     auto direct_it = font_list_.find(family);
378:     if (direct_it != font_list_.end()) {
379:       FontFaceInfo* font = direct_it->second.get();
380:       if (font->IsEligibleForFindFont(charset_flag, charset)) {
381:         iBestSimilar = font->SimilarityScore(weight, italic, pitch_family,
382:                                              must_match_name);
383:         pFind = font;
384:         if (iBestSimilar == FontFaceInfo::kSimilarityScoreMax) {
385:           return font;
386:         }
387:       }
388:     }
389:   }
390: 
391:   ByteStringView bsFamily = family.AsStringView();
392:   for (const auto& it : font_list_) {
393:     FontFaceInfo* font = it.second.get();
394:     if (!font->IsEligibleForFindFont(charset_flag, charset)) {
395:       continue;
396:     }
397:     int32_t iSimilarValue = font->SimilarityScore(
398:         weight, italic, pitch_family,
399:         must_match_name &&
400:             bsFamily.GetLength() == font->face_name_.GetLength());
401:     if (IsBetterMatch(font, iSimilarValue, pFind, iBestSimilar, charset, family,
402:                       must_match_name)) {
403:       iBestSimilar = iSimilarValue;
404:       pFind = font;
405:     }
406:   }
407: 
408:   if (pFind) {
409:     return pFind;
410:   }
411: 
412:   if (charset == FX_Charset::kANSI && FontFamilyIsFixedPitch(pitch_family)) {
413:     auto* courier_new = GetFont("Courier New");
414:     if (courier_new) {
415:       return courier_new;
416:     }
417:   }
418: 
419:   return nullptr;
420: }
