435: size_t CFX_FolderFontInfo::GetFontData(void* hFont,
436:                                        uint32_t table,
437:                                        pdfium::span<uint8_t> buffer) {
438:   if (!hFont) {
439:     return 0;
440:   }
441: 
442:   const FontFaceInfo* font = static_cast<FontFaceInfo*>(hFont);
443:   uint32_t datasize = 0;
444:   uint32_t offset = 0;
445:   if (table == SystemFontInfoIface::kTableNone) {
446:     datasize = font->font_offset_ ? 0 : font->file_size_;
447:   } else if (table == SystemFontInfoIface::kTableTTCF) {
448:     datasize = font->font_offset_ ? font->file_size_ : 0;
449:   } else {
450:     size_t nTables = font->font_tables_.GetLength() / 16;
451:     for (size_t i = 0; i < nTables; i++) {
452:       // TODO(tsepez): iterate over span.
453:       pdfium::span<const uint8_t> p =
454:           font->font_tables_.unsigned_span().subspan(i * 16);
455:       if (fxcrt::GetUInt32MSBFirst(p.first<4u>()) == table) {
456:         offset = fxcrt::GetUInt32MSBFirst(p.subspan<8u, 4u>());
457:         datasize = fxcrt::GetUInt32MSBFirst(p.subspan<12u, 4u>());
458:       }
459:     }
460:   }
461: 
462:   if (!datasize || buffer.size() < datasize) {
463:     return datasize;
464:   }
465: 
466:   std::unique_ptr<FILE, FxFileCloser> pFile(
467:       fopen(font->file_path_.c_str(), "rb"));
468:   if (!pFile) {
469:     return 0;
470:   }
471: 
472:   if (fseek(pFile.get(), offset, SEEK_SET) < 0) {
473:     return 0;
474:   }
475:   if (fxcrt::spanread(buffer.first(datasize), pFile.get()).size() != datasize) {
476:     return 0;
477:   }
478:   return datasize;
479: }
