588: int32_t CFX_FolderFontInfo::FontFaceInfo::SimilarityScore(
589:     int weight,
590:     bool italic,
591:     int pitch_family,
592:     bool exact_match_bonus) const {
593:   int32_t score = 0;
594:   if (FontStyleIsForceBold(styles_) == (weight > 400)) {
595:     score += 16;
596:   }
597:   if (FontStyleIsItalic(styles_) == italic) {
598:     score += 16;
599:   }
600:   if (FontStyleIsSerif(styles_) == FontFamilyIsRoman(pitch_family)) {
601:     score += 16;
602:   }
603:   if (FontStyleIsScript(styles_) == FontFamilyIsScript(pitch_family)) {
604:     score += 8;
605:   }
606:   if (FontStyleIsFixedPitch(styles_) == FontFamilyIsFixedPitch(pitch_family)) {
607:     score += 8;
608:   }
609:   if (exact_match_bonus) {
610:     score += 4;
611:   }
612:   DCHECK_LE(score, kSimilarityScoreMax);
613:   return score;
614: }
